func (a *Agent) fetchHTTP(ctx context.Context, ep Endpoint, timeout time.Duration) Observation {
	endpointCtx, cancel := context.WithTimeout(ctx, 90*time.Second)
	defer cancel()
	firstTimeout := timeout
	if ep.URL == "" && timeout > time.Nanosecond {
		firstTimeout = timeout / 2
	}
	obs := a.fetchHTTPOnce(endpointCtx, ep, firstTimeout)
	if ep.URL != "" || obs.Error == "" || obs.StatusCode != 0 {
		return obs
	}
	firstError := obs.Error
	alternate := ep
	scheme := "https"
	if strings.HasPrefix(obs.URL, "https://") {
		scheme = "http"
	}
	alternate.URL, _ = endpointURLWithScheme(ep, scheme)
	alt := a.fetchHTTPOnce(endpointCtx, alternate, timeout)
	if alt.Error == "" || alt.StatusCode != 0 {
		return alt
	}
	obs.Error = firstError + "; alternate protocol: " + alt.Error
	return obs
}

func TestHTTPProtocolFallbackSharesEndpointTimeout(t *testing.T) {
	listener, err := net.Listen("tcp4", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()
	var mu sync.Mutex
	var connections []net.Conn
	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			conn, err := listener.Accept()
			if err != nil {
				return
			}
			mu.Lock()
			connections = append(connections, conn)
			mu.Unlock()
		}
	}()
	defer func() {
		_ = listener.Close()
		<-done
		mu.Lock()
		defer mu.Unlock()
		for _, conn := range connections {
			_ = conn.Close()
		}
	}()

	a, err := New(Config{ControlURL: "http://127.0.0.1:1", JoinToken: "join", InstanceID: "test", Hostname: "test", SessionID: "test", AllowPrivateTargets: true})
	if err != nil {
		t.Fatal(err)
	}
	_, portText, _ := net.SplitHostPort(listener.Addr().String())
	port, _ := strconv.Atoi(portText)
	started := time.Now()
	obs := a.fetchHTTP(context.Background(), Endpoint{IP: "127.0.0.1", Port: port}, 200*time.Millisecond)
	elapsed := time.Since(started)
	if obs.Error == "" {
		t.Fatal("silent endpoint unexpectedly returned a response")
	}
	time.Sleep(20 * time.Millisecond)
	mu.Lock()
	accepted := len(connections)
	mu.Unlock()
	if accepted != 2 {
		t.Fatalf("protocol fallback opened %d connections; want both protocol attempts", accepted)
	}
	if elapsed > 300*time.Millisecond {
		t.Fatalf("protocol fallback exceeded the shared endpoint budget: %v", elapsed)
	}
}
